const test = require('node:test');
const assert = require('node:assert/strict');
const { acceptsAttachment } = require('../attachments.cjs');
test('compare the final suffix using the allowlist representation', () => {
  for (const name of ['forms/permit.pdf','photo.jpg','notes.v2.pdf','folder.pdf/image.jpg']) {
    assert.equal(acceptsAttachment(name), true);
  }
  for (const name of ['photo.JPG','permit.PDF','permit.pdf.exe','readme','.pdf','folder.pdf/readme','file.','']) {
    assert.equal(acceptsAttachment(name), false);
  }
});

